const toId = (v) => {
  const s = String(v || '').trim();
  const m = s.match(/linkedin\.com\/in\/([^/?#]+)/i);
  return (m ? m[1] : s).replace(/\/$/, '').toLowerCase();
};
const done = new Set();
for (const r of $('Read Already Enriched').all()) {
  const id = toId(r.json.public_identifier || r.json.linkedin_url);
  if (id) done.add(id);
}
const seen = new Set();
const out = [];
for (const r of $('Read Profiles to Enrich').all()) {
  const url = r.json.linkedin_url || r.json['LinkedIn URL'] || '';
  const id = toId(url);
  if (!id || done.has(id) || seen.has(id)) continue;
  seen.add(id);
  out.push({ json: { linkedin_url: url, identifier: id } });
}
return out;

const src = $('Loop Over Profiles').item.json;
const p = $json || {};
const jobs = Array.isArray(p.work_experience) ? p.work_experience : [];
const current = jobs.find(j => !j.end) || jobs[0] || {};
const past = jobs.filter(j => j !== current).slice(0, 3).map(j => `${j.position || ''} @ ${j.company || ''}`.trim()).join('; ');
const names = (arr, key) => (Array.isArray(arr) ? arr : []).map(x => typeof x === 'string' ? x : (x[key] || x.name || '')).filter(Boolean);
return { json: {
  linkedin_url: src.linkedin_url,
  public_identifier: p.public_identifier || src.identifier,
  provider_id: p.provider_id || '',
  first_name: p.first_name || '',
  last_name: p.last_name || '',
  headline: p.headline || '',
  location: p.location || '',
  current_title: current.position || '',
  current_company: current.company || '',
  current_role_since: current.start || '',
  past_roles: past,
  education: names(p.education, 'school').join('; '),
  skills: names(p.skills, 'name').slice(0, 10).join(', '),
  languages: names(p.languages, 'name').join(', '),
  summary: String(p.summary || '').slice(0, 500),
  open_profile: p.is_open_profile === true,
  premium: p.is_premium === true,
  network_distance: p.network_distance || '',
  followers: p.follower_count || '',
  status: p.provider_id ? 'enriched' : 'not found',
  enriched_at: new Date().toISOString()
} };
